7. Create `apps/web/src/typescale.test.ts` exactly:
```ts
// #2107: the board's text takes its sizes from one type scale, typescale.css, and its faces from
// fonts.css's three families, and no stylesheet gains a size or a face of its own unless this file
// says so.

import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

const SRC = dirname(fileURLToPath(import.meta.url));

/** The scale's size limit: a new step raises it in the same change, in plain sight. */
const TYPE_MAX = 10;
/** The step the board's body is set in; every other step's em form is a fraction of it. */
const BODY_STEP = "md";
/** The faces a stylesheet may name: fonts.css's three families, or its parent's. */
const FAMILIES = ["inherit", "var(--font-display)", "var(--font-text)", "var(--font-mono)"];

const STEP = /var\(--type-[a-z0-9]+(?:-em)?\)/;
/** A viewport or container term, which a clamp() or max() may hold beside a step. */
const FLUID = /\d*\.?\d+(?:vw|vh|vmin|vmax|dvh|svh|lvh|cqw|cqh|cqi|cqb|cqmin|cqmax)\b/g;
const KEYWORD = /\b(?:xx-small|x-small|small|medium|large|x-large|xx-large|xxx-large|smaller|larger)\b/;

/** Every font-size, font-family and font shorthand `css` states off the scale, outside its comments. */
function offScale(css: string): string[] {
  const code = css.replace(/\/\*[\s\S]*?\*\//g, " ");
  const found: string[] = [];
  for (const match of code.matchAll(/(?<![\w-])font-size\s*:\s*([^;}]+)/g)) {
    const value = (match[1] ?? "").trim();
    const rest = value.replace(/var\(--[a-z0-9-]+\)/g, "").replace(FLUID, "");
    if (value !== "inherit" && (!STEP.test(value) || /\d/.test(rest) || KEYWORD.test(rest))) found.push(`font-size: ${value}`);
  }
  for (const match of code.matchAll(/(?<![\w-])font-family\s*:\s*([^;}]+)/g)) {
    const value = (match[1] ?? "").trim();
    if (!FAMILIES.includes(value)) found.push(`font-family: ${value}`);
  }
  for (const match of code.matchAll(/(?<![\w-])font\s*:\s*([^;}]+)/g)) {
    const value = (match[1] ?? "").trim();
    if (value !== "inherit") found.push(`font: ${value.replace(/\s+/g, " ")}`);
  }
  return found;
}

function files(dir: string, ending: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return name === "test" ? [] : files(path, ending);
    return name.endsWith(ending) ? [path] : [];
  });
}

const SHEETS = files(SRC, ".css").map((path) => relative(SRC, path).replaceAll("\\", "/")).sort();
const read = (sheet: string): string => readFileSync(join(SRC, sheet), "utf8");

/** The board's stylesheets, as palette.test.ts has them: index.css and game/'s, but the deck builder's and table.css. */
const BOARD_SHEETS = SHEETS.filter(
  (sheet) => sheet === "index.css" || (sheet.startsWith("game/") && !sheet.startsWith("game/deckbuilder/") && sheet !== "game/table.css"),
);

/** Every other sheet's own sizes and faces: one that loses some lowers its number, and none gains one. */
const UNSCALED: Record<string, number> = {
  "audio/audio.css": 2,
  "auth/auth.css": 4,
  "auth/code-field.css": 11,
  "auth/consent.css": 3,
  "auth/tavern.css": 23,
  "auth/two-step.css": 1,
  "cards/cards.css": 29,
  "cards/cardstate.css": 9,
  "cards/inspect/inspect.css": 34,
  "cards/inspect/list-play.css": 1,
  "cards/keywords.css": 3,
  "cards/marks.css": 1,
  "cards/wheel/wheel.css": 3,
  "collection/collection.css": 10,
  "creator/creator.css": 8,
  "duos/duos.css": 14,
  "economy/economy.css": 6,
  "economy/xp.css": 1,
  "emotes/emotes.css": 7,
  "emotes/portrait.css": 3,
  "fx/fx.css": 8,
  "game/deckbuilder/deckbuilder.css": 19,
  "game/deckbuilder/workshop.css": 29,
  "i18n/language.css": 1,
  "packs/pack-object.css": 1,
  "packs/packs.css": 4,
  "patches/patches.css": 30,
  "practice/practice.css": 42,
  "practice/sandbox.css": 3,
  "routes/account.css": 3,
  "routes/game-banner.css": 5,
  "routes/landing.css": 20,
  "routes/lobby.css": 54,
  "routes/privacy.css": 5,
  "routes/purchases.css": 2,
  "routes/site-footer.css": 1,
  "routes/stats.css": 35,
  "settings/changeEmail.css": 1,
  "settings/settings.css": 12,
  "shop/shop.css": 2,
  "together/together.css": 10,
  "tutorial/path-visibility.css": 3,
  "tutorial/tutorial.css": 33,
};

const STEPS = [...read("typescale.css").matchAll(/^\s*--type-([a-z0-9]+):\s*(\d+)px;$/gm)].map((match) => ({
  name: match[1] ?? "",
  px: Number(match[2]),
}));
const EM_FORMS = [...read("typescale.css").matchAll(/^\s*--type-([a-z0-9]+)-em:\s*calc\((\d+)em \/ (\d+)\);$/gm)].map((match) => ({
  name: match[1] ?? "",
  px: Number(match[2]),
  over: Number(match[3]),
}));

describe("#2107 the type scale", () => {
  it("#2107 typescale.css names at most TYPE_MAX sizes in px, smallest first, each but the body's with its em form, and nothing else", () => {
    const sizes = STEPS.map((step) => step.px);
    expect(STEPS.length).toBeGreaterThan(0);
    expect(STEPS.length).toBeLessThanOrEqual(TYPE_MAX);
    expect(new Set(sizes).size, "two names for one size").toBe(sizes.length);
    expect(sizes).toEqual([...sizes].sort((a, b) => a - b));
    const body = STEPS.find((step) => step.name === BODY_STEP)?.px;
    expect(body).toBeDefined();
    expect(EM_FORMS).toEqual(STEPS.filter((step) => step.name !== BODY_STEP).map((step) => ({ name: step.name, px: step.px, over: body })));
    const text = read("typescale.css").replace(/\/\*[\s\S]*?\*\//g, "");
    const rest = text.replace(/^\s*--type-[a-z0-9]+:\s*\d+px;$/gm, "").replace(/^\s*--type-[a-z0-9]+-em:\s*calc\(\d+em \/ \d+\);$/gm, "");
    expect(rest.replace(/\s+/g, "")).toBe(":root{}");
    expect(read("index.css")).toMatch(/^@import "\.\/fonts\.css";\n@import "\.\/palette\.css";\n@import "\.\/typescale\.css";\n/);
  });

  it("#2107 the board's body is set in the body step, which the em forms are fractions of", () => {
    const css = read("index.css");
    expect(css).toMatch(/\nbody \{[^}]*\n {2}font-family: var\(--font-text\);\n {2}font-size: var\(--type-md\);/);
    expect(css).toMatch(/\n\.app-shell\.app-shell--wide \{[^}]*\n {2}font-size: var\(--type-md\);/);
  });

  it("#2107 every var(--type-…) names a step, only typescale.css declares one, and only fonts.css declares a family", () => {
    const names = new Set([...STEPS.map((step) => `--type-${step.name}`), ...EM_FORMS.map((form) => `--type-${form.name}-em`)]);
    for (const sheet of SHEETS) {
      const css = read(sheet);
      for (const match of css.matchAll(/var\((--type-[a-z0-9-]+)\)/g)) expect(names.has(match[1] ?? ""), `${sheet}: ${match[0]}`).toBe(true);
      if (sheet !== "typescale.css") expect(css, sheet).not.toMatch(/--type-[a-z0-9-]+\s*:/);
      if (sheet !== "fonts.css") expect(css, sheet).not.toMatch(/--font-[a-z0-9-]+\s*:/);
    }
    expect([...read("fonts.css").matchAll(/^\s*(--font-[a-z0-9-]+):/gm)].map((match) => match[1])).toEqual([
      "--font-display",
      "--font-text",
      "--font-mono",
    ]);
  });
});

describe("#2107 no one-off sizes or faces", () => {
  it("#2107 the board's stylesheets state no size but the scale's and no face but the three families", () => {
    expect(BOARD_SHEETS.length).toBeGreaterThan(20);
    const found = BOARD_SHEETS.flatMap((sheet) => offScale(read(sheet)).map((declaration) => `${sheet}: ${declaration}`));
    expect(found, "name a step (typescale.css) or a family (fonts.css) instead").toEqual([]);
  });

  it("#2107 no other stylesheet gains a size or a face of its own", () => {
    const counts: Record<string, number> = {};
    for (const sheet of SHEETS) {
      if (sheet === "fonts.css" || sheet === "typescale.css" || BOARD_SHEETS.includes(sheet)) continue;
      const own = offScale(read(sheet)).length;
      if (own > 0) counts[sheet] = own;
    }
    expect(counts, "take the size from typescale.css and the face from fonts.css; a sheet that loses some lowers its number in UNSCALED").toEqual(UNSCALED);
  });

  it("#2107 the board's components set no size or face inline", () => {
    const components = files(join(SRC, "game"), ".tsx").filter((path) => !path.endsWith(".test.tsx"));
    expect(components.length).toBeGreaterThan(20);
    for (const path of components) expect(readFileSync(path, "utf8"), relative(SRC, path)).not.toMatch(/\bfont(?:Size|Family)\b|\bfont-(?:size|family)\b/);
  });
});
```

8. `apps/web/README.md`: after the paragraph that begins "The colours are one palette (#2105)", add a blank line and:
"The text is one type scale (#2107): `src/typescale.css`, imported by `index.css` after the palette, ten sizes from `--type-3xs` (9px) to `--type-4xl` (30px), the board's body being `--type-md` (13px). Each but `--type-md` has an em form, `--type-<step>-em`, the step over 13px, for text that scales with its box (the board, a card), where `--type-md`'s is `inherit`. The faces are `fonts.css`'s three families: `--font-display`, `--font-text` and `--font-mono`. A board stylesheet gives every `font-size` a step (a `clamp()` or `max()` may hold a viewport or container term beside one), every `font-family` a family or `inherit`, and `font` only `inherit`. `src/typescale.test.ts` checks this, holds every other stylesheet to its count in `UNSCALED`, and keeps `src/game/`'s components from setting a size or a face inline."

**Tests.**

`apps/web/src/typescale.test.ts` (step 7), six tests: the scale's shape, ten steps at most (`TYPE_MAX`), each em form `step/13`, and the import order; body and `.app-shell--wide` set in `--type-md`; every `var(--type-…)` resolves, only `typescale.css` declares `--type-*` and only `fonts.css` declares `--font-*`, which are exactly the three; board sheets off-scale list is `[]`; other sheets equal `UNSCALED`; `src/game/**/*.tsx` sets no font inline. Before steps 3–5 this test fails 4 of its 6 tests (checked on a scratch copy). After them it passes, and so does `palette.test.ts` (12/12 checked).

Commands, from the repository root:
- `pnpm --dir apps/web exec vitest run src/typescale.test.ts src/palette.test.ts`
- `pnpm --dir apps/web test` (the whole web suite: other tests read these stylesheets)
- `pnpm --dir apps/web typecheck`
- `pnpm exec eslint apps/web/src/typescale.test.ts`

If `UNSCALED` mismatches, do not edit any non-board sheet. Re-check that step 5 touched only the 18 listed files.

**Done when.**
- [ ] `typescale.css` exists with the ten steps and nine em forms. `--font-mono` is in `fonts.css`, `index.css` imports the scale third, and body and showcase have no `font:` shorthand.
- [ ] Step 6's grep prints nothing.
- [ ] `typescale.test.ts` and `palette.test.ts` pass, and so do the whole web suite, typecheck and eslint.
- [ ] `/tmp/typescale.sed` is not in the worktree, and `git status` shows only the 22 files in the table.
- [ ] The harness checks (rustfmt, catalog, patches, rulings, clippy, cargo tests, web tests) pass. No Rust, catalog or ruling change, so no patch fragment is needed (#2164 had none).

**Risks.**
- Visual drift. Sizes move by a pixel or a few percent, by design. The largest moves are:
  - `.turn-mechanism > .clock` 0.62em → 0.69em
  - the facedown pill's floor 8px → 9px
  - `market.css` 1.3rem → 22px
  - 14px → 13px in the prompt and notices
  - 1.05em → `inherit`
  - the showcase ribbon's face, ui-serif → Alegreya, and its ordinal's, ui-sans-serif → Inter

  Known floors still hold: the prompt's number ≥18px (now 19), inputs 16px (`--type-xl`), and the keyword chips, which `cards/cards.css` sets and which is not touched. Card faces (`.cf`) take their sizes from `cards.css` container units, so board.css's `.card-*` changes barely reach them.
- Menus. Of the board sheets only `index.css` styles menus, and its sizes stay or shrink (the phone `h1` goes from 24px to 22px), so per-PR e2e smoke 46 (one screen, R1581000) should hold.
- The `font` shorthand reset `font-style` and `font-variant`. Its ancestors set neither, so the longhands render the same.
- Daily checks. Overflow is checked only by the daily component specs (`board-layout`, `card-faces`, `mobile-ux`, `meditative-prompts`). If Cypress runs here, run `pnpm --dir e2e exec cypress run --component --spec cypress/component/board-layout.cy.tsx,cypress/component/mobile-ux.cy.tsx`. If it doesn't, say so in the report and don't claim it.
- Unaffected: CSS only, so no determinism, replay or hidden-information effect. `scripts/ci-scope.sh` needs nothing, since the test reads only `apps/web/src`.

**Open questions.**
- Ten steps against "a handful". I kept 9/10/11/12/13 and 15/16 apart because:
  - 16px is iOS's input floor and 15px the menus' base.
  - The clock's two urgent sizes (1.12em, 1.26em) need both 15/13 and 16/13.
  - The board's small badges (0.62–0.72em) need 9/13.

  A person may prune a step: delete it in `typescale.css`, lower `TYPE_MAX`, and re-map its uses.
- Rejected alternatives:
  - A px-only scale: it would break the board's em chain (`.board` 0.92em on phones, `.card` 0.85em).
  - A separate em ladder: about 18 names in all.
  - Ties go to the smaller step to avoid overflow.
  - `font-weight`, `line-height` and `letter-spacing` are out of scope.
  - The menus' and cards' sheets stay unmigrated, held by `UNSCALED` as the palette did. A follow-up issue can move them.
  - `BOARD_SHEETS` is copied from `palette.test.ts` rather than shared, so the merged palette test stays untouched.
